result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/selection/src/model.ts", "content": "/**
 * Selection-model logic for a file-manager list view.
 *
 * Rules implemented (matching a typical desktop file explorer,
 * e.g. Windows Explorer / macOS Finder / VS Code lists):
 *
 * R1. Plain click (no ctrl, no shift):
 *     - Replaces the entire selection with just the clicked item.
 *     - The clicked item becomes BOTH the anchor and the focus.
 *
 * R2. Ctrl-click (no shift):
 *     - Toggles membership of the clicked item in the selection.
 *     - The anchor does NOT move, except when no anchor exists yet:
 *       then the clicked item becomes the anchor (so a later shift-click
 *       has a range origin).
 *     - The focus moves to the clicked item.
 *
 * R3. Anchor survival (deselection rule):
 *     - Ctrl-clicking the anchor OFF does not clear or move the anchor.
 *       A subsequent shift-click still extends the range from the original
 *       anchor position, exactly as long as no new anchor has been set.
 *
 * R4. Shift-click (no ctrl):
 *     - Selects the contiguous range [anchor..clicked] inclusive,
 *       REPLACING whatever selection existed before ("range shrink":
 *       shift-clicking inside a previously selected range re-selects only
 *       the smaller range).
 *     - If there is no anchor yet, the clicked item becomes the anchor
 *       and the sole selection.
 *
 * R5. Ctrl-shift-click:
 *     - Computes the contiguous range [anchor..clicked] and UNIONS it
 *       into the existing selection; prior selections are preserved
 *       ("extend additively").
 *     - The anchor does not move.
 *     - With no anchor, falls back to additive selection of the single
 *       clicked item (which also becomes the anchor).
 */

export interface SelectModifiers {
  ctrl?: boolean;
  shift?: boolean;
}

export interface SelectionModel<Id> {
  /** Apply a click on `id` with the given keyboard modifiers. */
  select(id: Id, modifiers?: SelectModifiers): void;
  /** Currently selected ids (defensive copy-free read-only view). */
  readonly selected: Set<Id>;
  /** Range origin for shift-operations, or null if none set yet. */
  readonly anchor: Id | null;
}

export function createSelection<Id>(ids: readonly Id[]): SelectionModel<Id> {
  const indexOf = new Map<Id, number>();
  ids.forEach((id, i) => indexOf.set(id, i));

  const selected = new Set<Id>();
  let anchor: Id | null = null;

  /** Contiguous inclusive range between two ids, honoring list order. */
  function range(from: Id, to: Id): Id[] {
    const a = indexOf.get(from)!;
    const b = indexOf.get(to)!;
    return ids.slice(Math.min(a, b), Math.max(a, b) + 1);
  }

  return {
    get selected() {
      return selected;
    },
    get anchor() {
      return anchor;
    },
    select(id, modifiers) {
      const { ctrl = false, shift = false } = modifiers ?? {};

      // R4/R5 precondition: shift means "operate on the anchored range".
      if (shift && anchor !== null && indexOf.has(anchor)) {
        const r = range(anchor, id);
        if (ctrl) {
          // R5: extend additively — keep prior selections, add the range.
          for (const x of r) selected.add(x);
        } else {
          // R4: replace the whole selection with the (possibly shrunk) range.
          selected.clear();
          for (const x of r) selected.add(x);
        }
        return;
      }

      if (shift) {
        // R4 fallback: shift-click with no usable anchor acts like a plain click.
      }

      if (ctrl && !shift) {
        // R2: toggle membership.
        if (selected.has(id)) {
          selected.delete(id);
          // R3: anchor survives being toggled off.
        } else {
          selected.add(id);
        }
        // R2: anchor only set if none exists yet.
        if (anchor === null || !indexOf.has(anchor)) anchor = id;
        return;
      }

      // R1 (and the shift-without-anchor fallback): single selection.
      selected.clear();
      selected.add(id);
      anchor = id;
    },
  };
}
"})
