result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/selection/tests/model.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { createSelection } from '../src/model';

const IDS = ['a', 'b', 'c', 'd', 'e'];

describe('file-manager selection model', () => {
  it('plain click then shift-click selects the contiguous range', () => {
    const s = createSelection(IDS);
    s.select('b'); // plain: {b}, anchor b
    expect([...s.selected]).toEqual(['b']);
    s.select('d', { shift: true }); // range b..d replaces selection
    expect([...s.selected]).toEqual(['b', 'c', 'd']);
    expect(s.anchor).toBe('b');
  });

  it('ctrl toggles; toggling the anchor off keeps the anchor for later shift-clicks', () => {
    const s = createSelection(IDS);
    s.select('b'); // anchor = b, selection {b}
    s.select('b', { ctrl: true }); // toggle off the anchor itself
    expect(s.selected.size).toBe(0);
    // R3: anchor survives deselection — shift-click still extends from b.
    s.select('d', { shift: true });
    expect([...s.selected]).toEqual(['b', 'c', 'd']);
    expect(s.anchor).toBe('b');
  });

  it('ctrl-click without prior anchor sets the anchor on first selection', () => {
    const s = createSelection(IDS);
    s.select('a', { ctrl: true });
    expect([...s.selected]).toEqual(['a']);
    expect(s.anchor).toBe('a');
    s.select('c', { ctrl: true }); // toggle c on, anchor stays a
    expect([...s.selected]).toEqual(['a', 'c']);
    expect(s.anchor).toBe('a');
    s.select('e', { ctrl: true }); // union range a..e with prior selection
    expect([...s.selected]).toEqual(['a', 'b', 'c', 'd', 'e']);
  });

  it('shift-click inside a prior range shrinks the selection (replace semantics)', () => {
    const s = createSelection(IDS);
    s.select('a');
    s.select('e', { shift: true }); // {a,b,c,d,e}
    expect(s.selected.size).toBe(5);
    s.select('c', { shift: true }); // shrink back to a..c
    expect([...s.selected]).toEqual(['a', 'b', 'c']);
    expect(s.anchor).toBe('a'); // anchor unchanged by shift operations
  });

  it('ctrl-shift-click extends the range additively without dropping prior selections', () => {
    const s = createSelection(IDS);
    s.select('a'); // anchor a, {a}
    s.select('c', { ctrl: true }); // toggle on c -> {a,c}
    s.select('e', { ctrl: true, shift: true }); // add range a..e to prior set
    expect([...s.selected]).toEqual(['a', 'b', 'c', 'd', 'e']);
    expect(s.anchor).toBe('a');

    // Additive over a disjoint prior selection too:
    const t = createSelection(['1', '2', '3', '4', '5', '6']);
    t.select('2');
    t.select('6', { ctrl: true }); // {2,6}
    t.select('4', { ctrl: true, shift: true }); // add 2..4 -> {2,3,4,6}
    expect([...t.selected]).toEqual([2, 3, 4, 6].map(String));
    expect(t.anchor).toBe('2');
  });

  it('edge cases: first click is plain, shift with no anchor, ctrl-shift with no anchor', () => {
    // Shift-click as the very first action selects just that item and anchors it.
    const s1 = createSelection(IDS);
    s1.select('d', { shift: true });
    expect([...s1.selected]).toEqual(['d']);
    expect(s1.anchor).toBe('d');

    // Ctrl-shift with no anchor falls back to additive single pick + anchors.
    const s2 = createSelection(IDS);
    s2.select('c', { ctrl: true, shift: true });
    expect([...s2.selected]).toEqual(['c']);
    expect(s2.anchor).toBe('c');
  });
});
"})
